export function historicalLeagueDrafts(year:number){
 const base=DATA[year]||{};
 return HISTORICAL_LEAGUE_ORDER.map(slug=>base[slug]||{slug,name:HISTORICAL_LEAGUE_NAMES[slug],sourceSheet:"",exists:false,status:"League did not exist in this draft year",teams:0,rounds:0,total:0,picks:[]});
}
export function historicalLeagueDraft(year:number,slug:string){return historicalLeagueDrafts(year).find(x=>x.slug===slug)||null}
